package com.example.leetcodetrainer.implementation.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="implementation_errors") public class ImplementationError { @Id private UUID id; @Column(name="implementation_record_id") private UUID implementationRecordId; @Enumerated(EnumType.STRING) private ImplementationErrorType errorType; @Enumerated(EnumType.STRING) private ErrorSource errorSource; @Enumerated(EnumType.STRING) private ErrorSeverity severity; @Lob private String description,failingInput,expectedOutput,actualOutput,rootCause,correction,preventionRule; @Column(name="recurrence_of_error_id") private UUID recurrenceOfErrorId; private Instant createdAt;
 protected ImplementationError(){} public ImplementationError(UUID id,UUID recordId,ImplementationErrorType type,ErrorSource source,ErrorSeverity severity,String input,String expected,String actual,String root,String correction,String prevention,UUID recurrence,Instant now){this.id=id;implementationRecordId=recordId;errorType=type;errorSource=source;this.severity=severity;failingInput=input;expectedOutput=expected;actualOutput=actual;rootCause=root;this.correction=correction;preventionRule=prevention;recurrenceOfErrorId=recurrence;createdAt=now;} public UUID getId(){return id;} public ImplementationErrorType getErrorType(){return errorType;} public UUID getRecurrenceOfErrorId(){return recurrenceOfErrorId;} }
